contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        require(_tos.length > 0);

        // Determine whether the low-level call to caddress would revert.
        // The selector used by C.transfer is bytes4(keccak256("transferFrom(address,address,uint256)"))
        bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));
        bool innerReverts;
        (bool ok, ) = caddress.call(abi.encodeWithSelector(id, from, _tos[0], v));
        innerReverts = !ok;

        bool outerReverted;
        try c.transfer(from, caddress, _tos, v) returns (bool) {
            outerReverted = false;
        } catch {
            outerReverted = true;
        }

        assert(!innerReverts || outerReverted);
    }

    receive() external payable {}
}

