        c = _c;
    }

    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        require(_tos.length > 0);

        bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));
        bool innerReverts = false;
        c.transfer(from, caddress, _tos, v);
        bool outerReverted = false;
        try c.transfer(from, caddress, _tos, v) returns (bool) {
            outerReverted = false;
        } catch {
            outerReverted = true;
        }
        if (_tos.length > 0) {
            (bool ok, ) = caddress.call(abi.encodeWithSelector(id, from, _tos[0], v));
            innerReverts = !ok;
        }

        assert(innerReverts == outerReverted);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address target, address[] memory tos, uint v) public payable {
        require(tos.length > 0, "tos must be non-empty");

        address callTarget = target;
        if (callTarget == address(0)) {
            callTarget = address(this);
        }

        bool reverted;
        bool result;
        try c.transfer(from, callTarget, tos, v) returns (bool r) {
            reverted = false;
            result = r;
        } catch {
            reverted = true;
            result = false;
        }

        assert(reverted || (result == true && tos.length > 0));
    }

    receive() external payable {}
}
